data.solution:
temps = []
for x in input().split(" "):
    temps.append(int(x))

averages = []
curr_temps = []
for t in temps:
    if t == -1:
        if curr_temps != []:
            averages.append(round(sum(curr_temps) / len(curr_temps)))
        curr_temps = []
    elif t < -500 or t > 500:
        pass
    else:
        curr_temps.append(t)

if curr_temps != []:
    averages.append(round(sum(curr_temps) / len(curr_temps)))

print('\n'.join([str(x) for x in averages]))
